export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const H = u * u / (2 * g);
  const F = m * g;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 40, w: 300, h: 370, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 40, w: 300, h: 370, title: 'Velocity over time', state: 'a = -g' }));
  o.push(sdk.axis('axis.h', { x: 70, y: 380, length: 290, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const py = 380 - y / 2.2 * 290;
  o.push(sdk.circle('ball.toss', 150, py, 24));
  o.push(...sdk.vector('vec.v', { x: 150, y: py }, { value: v, direction: 'up' }, { scale: 14, label: 'v' }));
  o.push(...sdk.vector('vec.a', { x: 190, y: py }, { value: -g, direction: 'up' }, { scale: 6, label: 'a' }));
  o.push(...sdk.callout(215, py - 30 < 80 ? 80 : py - 30, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = (a, b) => sdk.sample(s => u - g * s, a, b, 10).map(p => ({ x: p[0], y: p[1] }));
  const series = [{ label: 'v', kind: 'line', points: pts(0, Math.max(t, 0.01)) }, { label: 'v later', kind: 'line', points: pts(Math.max(t, 0.01), T) }];
  o.push(sdk.plot('plot.vt', { x: 340, y: 80, w: 285, h: 320, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series }));
  o.push(sdk.text('plot.vt.note', 480, 70, 'slope a = -g', { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F } };
}
